option.value:
# Script para configurar la API Key de Gemini # Autores: Diego Rocabado (305310) y Santiago Dirón (359644)
Write-Host "========================================" -ForegroundColor Cyan Write-Host " CONFIGURACIÓN DE GEMINI API KEY" -ForegroundColor Cyan Write-Host "========================================" -ForegroundColor Cyan Write-Host ""
# Paso 1: Verificar si ya existe $apiKeyActual = [System.Environment]::GetEnvironmentVariable('ERP_API_KEY', 'User')
if ($apiKeyActual) { Write-Host "✓ Variable ERP_API_KEY ya existe" -ForegroundColor Yellow Write-Host " Valor actual: $($apiKeyActual.Substring(0, [Math]::Min(20, $apiKeyActual.Length)))..." -ForegroundColor Gray Write-Host "" $respuesta = Read-Host "¿Deseas reemplazarla? (S/N)" if ($respuesta -ne 'S' -and $respuesta -ne 's') { Write-Host "Operación cancelada." -ForegroundColor Yellow exit } }
# Paso 2: Instrucciones Write-Host "" Write-Host "PASO 1: Obtener tu API Key" -ForegroundColor Green Write-Host " 1. Abre tu navegador" -ForegroundColor White Write-Host " 2. Ve a: https://aistudio.google.com/" -ForegroundColor White Write-Host " 3. Inicia sesión con tu cuenta de Google" -ForegroundColor White Write-Host " 4. Haz clic en 'Get API Key' o 'Obtener clave de API'" -ForegroundColor White Write-Host " 5. Copia la API Key completa" -ForegroundColor White Write-Host ""
# Abrir el navegador automáticamente Write-Host "¿Deseas abrir AI Studio en tu navegador ahora? (S/N): " -ForegroundColor Cyan -NoNewline $abrirNav = Read-Host if ($abrirNav -eq 'S' -or $abrirNav -eq 's') { Start-Process "https://aistudio.google.com/" Write-Host "✓ Navegador abierto. Por favor sigue los pasos arriba." -ForegroundColor Green Write-Host "" Write-Host "Presiona Enter cuando hayas copiado tu API Key..." -ForegroundColor Yellow Read-Host }
# Paso 3: Pedir la API Key Write-Host "" Write-Host "PASO 2: Pega tu API Key aquí" -ForegroundColor Green Write-Host "Formato esperado: AIzaSy..." -ForegroundColor Gray Write-Host "" $apiKey = Read-Host "Pega tu API Key"
# Validar formato básico if ([string]::IsNullOrWhiteSpace($apiKey)) { Write-Host "✗ Error: No se ingresó ninguna API Key" -ForegroundColor Red exit 1 }
$apiKey = $apiKey.Trim()
if (-not $apiKey.StartsWith("AIza")) { Write-Host "⚠ Advertencia: La API Key no tiene el formato esperado (debería empezar con 'AIza')" -ForegroundColor Yellow $continuar = Read-Host "¿Continuar de todas formas? (S/N)" if ($continuar -ne 'S' -and $continuar -ne 's') { Write-Host "Operación cancelada." -ForegroundColor Yellow exit } }
# Paso 4: Configurar la variable Write-Host "" Write-Host "PASO 3: Configurando variable de entorno..." -ForegroundColor Green
try { [System.Environment]::SetEnvironmentVariable('ERP_API_KEY', $apiKey, 'User') Write-Host "✓ Variable ERP_API_KEY configurada exitosamente!" -ForegroundColor Green } catch { Write-Host "✗ Error al configurar la variable: $_" -ForegroundColor Red exit 1 }
# Paso 5: Verificar Write-Host "" Write-Host "PASO 4: Verificando configuración..." -ForegroundColor Green $verificar = [System.Environment]::GetEnvironmentVariable('ERP_API_KEY', 'User')
if ($verificar -eq $apiKey) { Write-Host "✓ Verificación exitosa!" -ForegroundColor Green Write-Host " API Key configurada: $($apiKey.Substring(0, [Math]::Min(20, $apiKey.Length)))..." -ForegroundColor Gray } else { Write-Host "✗ Error: La verificación falló" -ForegroundColor Red exit 1 }
# Paso 6: Instrucciones finales Write-Host "" Write-Host "========================================" -ForegroundColor Cyan Write-Host " CONFIGURACIÓN COMPLETADA" -ForegroundColor Cyan Write-Host "========================================" -ForegroundColor Cyan Write-Host "" Write-Host "IMPORTANTE:" -ForegroundColor Yellow Write-Host "1. CIERRA IntelliJ IDEA completamente" -ForegroundColor White Write-Host "2. Vuelve a abrir IntelliJ IDEA" -ForegroundColor White Write-Host "3. Ejecuta tu aplicación: java Main" -ForegroundColor White Write-Host "" Write-Host "La integración con Gemini debería funcionar ahora." -ForegroundColor Green Write-Host "" Write-Host "Para probar desde esta terminal (sin reiniciar IntelliJ):" -ForegroundColor Cyan Write-Host " cd $PWD" -ForegroundColor Gray Write-Host " java Main" -ForegroundColor Gray Write-Host ""
# Preguntar si desea ejecutar ahora $ejecutar = Read-Host "¿Deseas ejecutar la aplicación ahora? (S/N)" if ($ejecutar -eq 'S' -or $ejecutar -eq 's') { Write-Host "" Write-Host "Ejecutando aplicación..." -ForegroundColor Green # Establecer la variable en la sesión actual también $env:ERP_API_KEY = $apiKey java Main }
